select 

from MST_FUND_BONUS_NOTICE
where FUND_ID = #{fundId,jdbcType=VARCHAR}
  and REG_DATE = #{regDate,jdbcType=DATE}

mapper.delete:
delete from MST_FUND_BONUS_NOTICE
where FUND_ID = #{fundId,jdbcType=VARCHAR}
  and REG_DATE = #{regDate,jdbcType=DATE}

mapper.update:
update MST_FUND_BONUS_NOTICE
